import { test, expect } from '@playwright/test';

test.describe('File Upload Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload'); // Replace with the actual URL of the upload page
  });

  test('should show error for unsupported file type', async ({ page }) => {
    const filePath = 'path/to/unsupported-file.txt'; // Replace with an actual unsupported file path
    await page.setInputFiles(getByLabel('File Upload'), filePath);
    await page.click(getByRole('button', { name: 'Upload' }));

    const errorMessage = await page.getByText('Unsupported file type. Please upload a valid file.'); // Replace with the actual error message
    await expect(errorMessage).toBeVisible();
  });

  test('should not show error for supported file type', async ({ page }) => {
    const filePath = 'path/to/supported-file.jpg'; // Replace with an actual supported file path
    await page.setInputFiles(getByLabel('File Upload'), filePath);
    await page.click(getByRole('button', { name: 'Upload' }));

    const successMessage = await page.getByText('File uploaded successfully.'); // Replace with the actual success message
    await expect(successMessage).toBeVisible();
  });
});
